const stage = input.previous;
if (stage?.verdict === 'revise') {
  return { stage, priorReview: stage };
}
const accepted = stage?.review ?? stage;
if (
  (accepted?.decisionSource === 'agent_review' && accepted.route === 'proceed') ||
  (accepted?.decisionSource === 'human' && accepted.decision === 'approved')
) {
  return { stage, priorReview: null };
}
throw new Error('Expected accepted plan or revision review');
